    display: flex;
    gap: 0.35rem;
    position: sticky;
    top: 0;
    z-index: 2;
    padding: 0.4rem 0;
    background: var(--ink, #101614);
  }

  .view-switch button {
    flex: 1;
    min-height: 40px;
    padding: 0.4rem 0.5rem;
    border-radius: 999px;
    border: 1px solid var(--line);
    background: transparent;
    color: var(--paper);
    font: inherit;
    font-size: 0.92rem;
    font-weight: 600;
    cursor: pointer;
  }

  .view-switch button[aria-pressed="true"] {
    background: var(--brass);
    border-color: var(--brass);
    color: var(--brass-ink);
  }

  .workspace[data-stage="plan"][data-view="plan"] .rail,
  .workspace[data-stage="plan"][data-view="plan"] .sources,
  .workspace[data-stage="plan"][data-view="brief"] .stage-main,
  .workspace[data-stage="plan"][data-view="brief"] .sources,
  .workspace[data-stage="plan"][data-view="sources"] .rail,
  .workspace[data-stage="plan"][data-view="sources"] .stage-main {
    display: none;
  }

  .progress li {
    padding: 0.25rem 0.55rem;
  }
}

@media (max-width: 640px) {
  .app-bar {
    gap: 0.5rem 0.75rem;
  }

  .progress {
    order: 3;
    width: 100%;
  }

  .progress li {
    flex: 1;
    text-align: center;
  }

  .timeline {
    padding-left: 1.1rem;
  }

  .stop {
    padding: 0.85rem;
  }

  .stop-seq {
    left: calc(-1.1rem - 0.85rem);
    width: 1.45rem;
    height: 1.45rem;
  }

  .checks div {
    grid-template-columns: 1fr;
    gap: 0;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .stop,
  .sources {
    animation: landing-rise 240ms ease;
  }
}

@media (prefers-reduced-motion: reduce) {
  .stop,
  .sources,
  .link-button,
  .view-switch button,
  .new-evening {
    animation: none;
    transition: none;
  }
}
